import json, numpy as np
from PIL import Image
from scipy.spatial.transform import Rotation
BASE=np.array([2.66655,-2.16344,.91737]);RB=np.array([[0,-1,0],[1,0,0],[0,0,1]])
def meta(run): return json.load(open('/app/runs/'+run+'/meta.json'))
def proprio(run):
 p=meta(run)['proprio'];return dict(zip(p['layout'],p['now']))
def command(run):
 p=proprio(run);s=json.load(open('/app/runs/spec.json'));return np.array([p['cmd_'+k] for k in s['action_types']['ee_pose']['layout']])
def points(run,cam):
 m=meta(run)['cameras'][cam];d=np.load('/app/runs/'+run+'/depth_'+cam+'.npy')[-1].astype(float);K=np.array(m['intrinsic_cv']);T=np.array(m['cam2world_gl']);v,u=np.indices(d.shape)
 pc=np.stack(((u-K[0,2])*d/K[0,0],-(v-K[1,2])*d/K[1,1],-d),-1)
 return pc@T[:3,:3].T+T[:3,3]
def project(run,cam,w):
 c=meta(run)['cameras'][cam];T=np.array(c['cam2world_gl']);K=np.array(c['intrinsic_cv']);p=(np.array(w)-T[:3,3])@T[:3,:3];return np.array([K[0,0]*p[0]/-p[2]+K[0,2],K[1,1]*-p[1]/-p[2]+K[1,2]])
def to_base(p):return RB.T@(np.array(p)-BASE)
def to_world(p):return RB@np.array(p)+BASE
if __name__=='__main__':
 run='initial';p=proprio(run)
 for h in ['left','right']:
  w=[p['eef_'+h+'_'+k] for k in 'xyz'];print(h,project(run,'egoview',w))
 pc=points(run,'egoview');im=np.array(Image.open('/app/runs/'+run+'/last/egoview.jpg'));mask=(im[:,:,0]>110)&(im[:,:,1]>100)&(im[:,:,2]<90);mask[:145]=False;mask[183:]=False;mask[:,:142]=False;mask[:,167:]=False
 ps=pc[mask];print('lemon surface bounds',np.min(ps,0),np.max(ps,0),np.median(ps,0))
